arguments.query:
query PlayNexusContextTest {
  games(search: "Assassin", first: 3, orderBy: "id", orderDir: "desc") {
    nodes {
      id
      name
      slug
      status
      studio { id name slug }
      platforms { id name slug }
      productCount
      videoCount
      products(first: 1, status: "published", visibility: "public") {
        nodes { id title slug status price }
        pageInfo { total hasMore }
      }
      content(first: 1, status: "published") {
        nodes { id type title slug status publishedAt }
        pageInfo { total hasMore }
      }
    }
    pageInfo { total first offset hasMore nextOffset }
  }
}
